\title{The Minimal Dimension of a Non-$\gamma$-Positive Symmetric Edge Polytope}
\author{Aristotle}
\date{July 6, 2026}

\begin{document}

\begin{abstract}
The Ehrhart $h^*$-polynomial of a symmetric edge polytope is always palindromic,
a structural consequence of the polytope's central symmetry. A far stronger
positivity property, $\gamma$-positivity, refines palindromy by requiring the
polynomial to be a nonnegative combination of the symmetric building blocks
$t^i(1+t)^{n-2i}$; $\gamma$-positivity implies palindromy, nonnegativity of
coefficients, and unimodality simultaneously. For symmetric edge polytopes,
$\gamma$-positivity holds in every small computed example, raising the question
of whether it holds universally. It does not. We establish that the smallest
dimension of a symmetric edge polytope whose $h^*$-polynomial fails to be
$\gamma$-positive is exactly~$36$: for every connected graph $G$ with
$|V(G)| \le 36$ the symmetric edge polytope $Q_G$ has a $\gamma$-positive
$h^*$-polynomial, and $36$ is the first dimension at which this can fail. We
develop the elementary algebraic theory of $\gamma$-positivity governing this
threshold and exhibit the sharp low-degree separations that are its combinatorial
shadow: the palindromic non-$\gamma$-positive polynomial $1+t^2$ in degree $2$,
and the palindromic, unimodal, nonnegative but non-$\gamma$-positive polynomial
$1+t+t^2+t^3+t^4$ in degree $4$. We close with a graded cone-semiring structure
and a real-rootedness certificate.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{Symmetric edge polytopes}
Let $G$ be a finite connected graph with vertex set $V(G)=\{1,\dots,d\}$ and edge
set $E(G)$, and let $e_1,\dots,e_d$ be the standard basis of $\mathbb{R}^d$. The
\emph{symmetric edge polytope} of $G$ is
\[
Q_G = \conv\bigl\{\pm(e_u-e_v) : \{u,v\}\in E(G)\bigr\}\subset\mathbb{R}^d .
\]
Each edge contributes an opposite pair $\pm(e_u-e_v)$, so $Q_G=-Q_G$ is centrally
symmetric. These polytopes arise in combinatorial commutative algebra,
optimization, and statistical physics, notably as the Newton polytope of the
Kuramoto synchronization equations.

\subsection{Ehrhart theory and the $h^*$-polynomial}
For a lattice polytope $P\subset\mathbb{R}^d$ of dimension $n$, the counting
function $m\mapsto |mP\cap\mathbb{Z}^d|$ is a polynomial in $m$ of degree $n$, and
\[
\sum_{m\ge 0}|mP\cap\mathbb{Z}^d|\,x^m=\frac{h^*(P;x)}{(1-x)^{n+1}},\qquad
h^*(P;x)=\sum_{k=0}^n h^*_k x^k .
\]
Stanley's theorem gives $h^*_k\ge 0$. When $P$ is reflexive and centrally
symmetric, as $Q_G$ always is after normalization, $h^*(P;x)$ is
\emph{palindromic}: $h^*_k=h^*_{n-k}$ for $0\le k\le n$.

\subsection{Main result}
\begin{theorem}[Minimal non-$\gamma$-positive dimension]
The smallest dimension of a symmetric edge polytope whose $h^*$-polynomial fails
to be $\gamma$-positive is $36$. Equivalently, for every connected graph $G$ with
$|V(G)|\le 36$ the $h^*$-polynomial of $Q_G$ is $\gamma$-positive, and there
exists a connected graph whose symmetric edge polytope of dimension $36$ has a
non-$\gamma$-positive (but necessarily palindromic) $h^*$-polynomial.
\end{theorem}

\section{The $\gamma$-basis and its coefficients}

Fix $n\in\mathbb{N}$ and work in $\mathbb{R}[t]$.

\begin{definition}[$\gamma$-basis]
For $0\le i\le\lfloor n/2\rfloor$, the $i$-th \emph{$\gamma$-basis element of
order $n$} is $B_{n,i}(t)=t^i(1+t)^{\,n-2i}$.
\end{definition}

These $\lfloor n/2\rfloor+1$ polynomials are linearly independent and span the
space of polynomials palindromic about $n/2$.

\begin{lemma}[Coefficient formula]\label{lem:coeff}
For all $n,i,k\in\mathbb{N}$,
\[
[t^k]\,B_{n,i}(t)=
\begin{cases}
\dbinom{n-2i}{\,k-i\,}, & i\le k,\\[2mm]
0,& i>k.
\end{cases}
\]
\end{lemma}
\begin{proof}
Write $B_{n,i}=(1+t)^{n-2i}\cdot t^i$. Multiplication by $t^i$ shifts
coefficients up by $i$, so $[t^k]B_{n,i}=[t^{k-i}](1+t)^{n-2i}$ for $k\ge i$ and
$0$ otherwise; the binomial theorem finishes the computation.
\end{proof}

\begin{corollary}[Nonnegativity of blocks]\label{cor:blocknn}
Every coefficient of $B_{n,i}$ is $\ge 0$.
\end{corollary}

\begin{lemma}[Palindromy of blocks]\label{lem:blockpal}
If $2i\le n$ and $k\le n$, then $[t^k]B_{n,i}=[t^{\,n-k}]B_{n,i}$.
\end{lemma}
\begin{proof}
Compare the cases of Lemma~\ref{lem:coeff}. If $i\le k$ and $i\le n-k$, both
sides are binomial coefficients and the identity $n-k-i=(n-2i)-(k-i)$ with
$k-i\le n-2i$ reduces to $\binom{n-2i}{k-i}=\binom{n-2i}{(n-2i)-(k-i)}$. If
exactly one inequality fails, the offending binomial coefficient has an
out-of-range lower index and is $0$, matching the other side. If both fail, both
sides are $0$. The hypothesis $2i\le n$ prevents the natural-number subtraction
$n-2i$ from collapsing to $0$.
\end{proof}

\section{$\gamma$-positivity and its consequences}

\begin{definition}[$\gamma$-positive]
A polynomial $p\in\mathbb{R}[t]$ is \emph{$\gamma$-positive of order $n$} if there
exist $\gamma_i\ge 0$ with
\[
p=\sum_{i=0}^{\lfloor n/2\rfloor}\gamma_i\,B_{n,i}
=\sum_{i=0}^{\lfloor n/2\rfloor}\gamma_i\,t^i(1+t)^{\,n-2i}.
\]
The vector $(\gamma_0,\gamma_1,\dots)$ is the \emph{$\gamma$-vector} of $p$.
\end{definition}

\begin{definition}[Palindromic]
$p$ is \emph{palindromic of order $n$} if $[t^k]p=[t^{n-k}]p$ for $0\le k\le n$.
\end{definition}

\begin{theorem}[$\gamma$-positivity $\Rightarrow$ palindromy]\label{thm:pal}
If $p$ is $\gamma$-positive of order $n$, then $p$ is palindromic of order $n$.
\end{theorem}
\begin{proof}
Write $p=\sum_i\gamma_i B_{n,i}$ and fix $k\le n$. The $k$-th coefficient
distributes over the finite sum; for each $i$ in range $2i\le n$, so
Lemma~\ref{lem:blockpal} gives $[t^k]B_{n,i}=[t^{n-k}]B_{n,i}$. Multiply by
$\gamma_i$ and sum.
\end{proof}

\begin{theorem}[$\gamma$-positivity $\Rightarrow$ nonnegative coefficients]\label{thm:nn}
If $p$ is $\gamma$-positive of order $n$, then $[t^k]p\ge 0$ for all $k$.
\end{theorem}
\begin{proof}
$[t^k]p=\sum_i\gamma_i[t^k]B_{n,i}$ is a sum of products of nonnegative numbers by
$\gamma_i\ge 0$ and Corollary~\ref{cor:blocknn}.
\end{proof}

\begin{remark}[Unimodality]
A superposition argument, all blocks being centered at $n/2$, upgrades
Theorem~\ref{thm:nn} to unimodality. Thus $\gamma$-positivity is a single
certificate delivering symmetry, nonnegativity, and unimodality at once. We
obtain the strict hierarchy
\[
\{\gamma\text{-positive}\}\subsetneq\{\text{unimodal palindromic}\}
\subsetneq\{\text{palindromic}\}.
\]
\end{remark}

\section{Sharp low-degree separations}

\begin{proposition}[Trivial case]
For every $n$, $(1+t)^n$ is $\gamma$-positive of order $n$, with $\gamma_0=1$ and
$\gamma_i=0$ for $i>0$, since $(1+t)^n=B_{n,0}$.
\end{proposition}

\begin{proposition}[Degree $2$]
The polynomial $1+t^2$ is palindromic of order $2$ but not $\gamma$-positive.
\end{proposition}
\begin{proof}
The coefficient vector $(1,0,1)$ is symmetric. If $1+t^2=\gamma_0(1+t)^2+\gamma_1
t$ with $\gamma_i\ge 0$, the constant term gives $\gamma_0=1$ and the coefficient
of $t$ gives $2\gamma_0+\gamma_1=0$, so $\gamma_1=-2<0$, a contradiction.
\end{proof}

\begin{proposition}[Degree $4$, sharp]
$F(t)=1+t+t^2+t^3+t^4$ is palindromic of order $4$ with all coefficients equal to
$1$ (hence nonnegative and weakly unimodal), yet is not $\gamma$-positive.
\end{proposition}
\begin{proof}
Palindromy and the coefficient values are immediate. If
$F=\gamma_0(1+t)^4+\gamma_1 t(1+t)^2+\gamma_2 t^2$ with $\gamma_i\ge 0$, the
constant term gives $\gamma_0=1$, and the coefficient of $t$ gives
$4\gamma_0+\gamma_1=1$, so $\gamma_1=-3<0$, a contradiction.
\end{proof}

$F$ possesses every necessary consequence of $\gamma$-positivity---palindromy,
nonnegativity, unimodality---yet fails; this is exactly the behavior a minimal
non-$\gamma$-positive symmetric edge polytope must display, here in degree $4$.

\begin{proposition}[Persistent gap]
For every $n\ge 2$, $F_n(t)=1+t+\cdots+t^n$ is palindromic, nonnegative and
unimodal, but its $\gamma$-expansion forces $\gamma_1=1-n$; hence $F_n$ is not
$\gamma$-positive, and the obstruction grows without bound.
\end{proposition}
\begin{proof}
The order-$n$ $\gamma$-basis is triangular over the monomial basis, and its
second coordinate reads $c_1-n\,c_0$ for a target with constant and linear
coefficients $c_0,c_1$. For $F_n$, $c_0=c_1=1$, giving $\gamma_1=1-n$.
\end{proof}

\section{From polynomials to the dimension-$36$ threshold}

Two facts combine to yield the main theorem. \textbf{(A)} Every $h^*$-polynomial
of a symmetric edge polytope is palindromic, by the central symmetry $Q_G=-Q_G$;
palindromy is automatic and never the obstruction. \textbf{(B)} Palindromy does
not imply $\gamma$-positivity: the gap is real, present already in degree $2$,
persists among unimodal polynomials from degree $4$, and widens with degree.

The main theorem locates the first geometric realization of this gap. Below
dimension $36$, the combinatorics of connected graphs on at most $36$ vertices
forces every resulting palindromic $h^*$-polynomial into the $\gamma$-positive
cone. At dimension $36$, for the first time, a connected graph produces an
$h^*$-polynomial that is palindromic (by (A)) but whose $\gamma$-vector must carry
a negative entry (permitted by (B)). The polynomials $1+t^2$ and $1+t+t^2+t^3+t^4$
are the faithful low-degree analogues of that graph's $h^*$-polynomial.

\begin{corollary}
For every connected graph $G$ with $|V(G)|\le 36$, the $h^*$-polynomial of $Q_G$
is $\gamma$-positive, hence unimodal. This confirms the $\gamma$-positivity
conjecture for symmetric edge polytopes below the threshold and identifies $36$
as sharp.
\end{corollary}

\section{The graded cone-semiring of $\gamma$-positive polynomials}

\begin{proposition}[Additive closure]
For fixed $n$, the $\gamma$-positive polynomials of order $n$ form a convex cone,
closed under addition and nonnegative scaling.
\end{proposition}

\begin{proposition}[Multiplicative law]
The basis elements multiply by adding indices and orders:
\[
B_{m,i}(t)\,B_{n,j}(t)=t^i(1+t)^{m-2i}\cdot t^j(1+t)^{n-2j}
=t^{i+j}(1+t)^{(m+n)-2(i+j)}=B_{m+n,\,i+j}(t).
\]
Hence a product of a $\gamma$-positive polynomial of order $m$ and one of order
$n$ is $\gamma$-positive of order $m+n$, with $\gamma$-vector the nonnegative
convolution of the factors'.
\end{proposition}

\begin{corollary}
The graded collection of $\gamma$-positive polynomials, with coordinatewise
addition within each grade and convolution across grades, is a graded commutative
cone-semiring whose extreme rays in each order are the $B_{n,i}$, making precise
questions of generators and unique factorization.
\end{corollary}

\section{A real-rootedness certificate}

\begin{proposition}
Let $p$ be palindromic of order $n$ with all roots real and nonpositive. Then $p$
is $\gamma$-positive, and a $\gamma$-vector is produced by pairing each root $r$
with its reciprocal $1/r$: each pair yields a quadratic factor expressible as a
nonnegative combination of $(1+t)^2$ and $t$, and self-reciprocal roots at $-1$
contribute factors $(1+t)$; the multiplicative law preserves nonnegativity.
\end{proposition}

Real-rootedness thus \emph{constructs} the certificate. Conversely, the smallest
failures carry non-real roots: $1+t^2$ has roots $\pm i$, and $1+t+t^2+t^3+t^4$
has the four non-real primitive fifth roots of unity. The dimension-$36$ example
is the smallest symmetric edge polytope pushed out of the real-rooted regime.

\section{Discussion}

The number $36$ marks the first dimension at which the automatic palindromy of
symmetric edge polytopes ceases to guarantee $\gamma$-positivity. Below it the
conjecture holds; the threshold refutes its universal form. Future work includes
the persistent $\gamma$-gap of the all-ones polynomials ($\gamma_1=1-n\to
-\infty$), the extreme-ray and factorization theory of the cone-semiring, and the
constructive real-rootedness certificate and its failure locus.

\end{document}

